import streamlit as st
import pandas as pd
import plotly.graph_objects as go
import sqlite3, hashlib, secrets, random, base64, html, json, re, os
from datetime import datetime, timedelta
from pathlib import Path

DB_PATH = Path(__file__).with_name("novacare.db")
APP_DIR = Path(__file__).parent
VERSION = "V2.2 · DISEASE-AWARE DEMO · AESS NOVA MISSION CONTROL"
LOGO_PATH = APP_DIR / "AESS NOVA Futuristic Compass Emblem.png"
LOGO_B64 = ""
def show_nova_logo(target, width=None):
    """Render the AESS NOVA logo; embedded fallback makes it independent of file paths."""
    if LOGO_PATH.exists():
        target.image(str(LOGO_PATH), use_container_width=(width is None), width=width)
    else:
        target.image(base64.b64decode(LOGO_B64), use_container_width=(width is None), width=width)

def logo_data_uri():
    """Logo as a data URI so it can sit inside the compact login card (works with or without the PNG file)."""
    try:
        if LOGO_PATH.exists():
            return "data:image/png;base64," + base64.b64encode(LOGO_PATH.read_bytes()).decode()
    except Exception:
        pass
    return "data:image/png;base64," + LOGO_B64


