try:
    APP_SECRETS = st.secrets
except FileNotFoundError:
    APP_SECRETS = {}
ADMIN_USER = APP_SECRETS.get("NOVACARE_ADMIN_USER", os.getenv("NOVACARE_ADMIN_USER", ""))
ADMIN_PASSWORD = APP_SECRETS.get("NOVACARE_ADMIN_PASSWORD", os.getenv("NOVACARE_ADMIN_PASSWORD", ""))
ADMIN_PASS_HASH = hashlib.sha256(ADMIN_PASSWORD.encode()).hexdigest() if ADMIN_PASSWORD else ""

# =====================================================================
# Database
# =====================================================================
def db():
    conn = sqlite3.connect(DB_PATH, timeout=10, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    with db() as c:
        c.executescript("""
        CREATE TABLE IF NOT EXISTS astronauts(
          id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, age INTEGER NOT NULL,
          photo BLOB, mission TEXT DEFAULT '', allergies TEXT DEFAULT '',
          surgeries TEXT DEFAULT '', chronic_diseases TEXT DEFAULT '',
          baseline_hr REAL, baseline_spo2 REAL, baseline_temp REAL, baseline_sleep REAL,
          created_at TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS devices(
          id INTEGER PRIMARY KEY AUTOINCREMENT, device_code TEXT UNIQUE NOT NULL,
          astronaut_id INTEGER, secret_hash TEXT NOT NULL, connection_type TEXT DEFAULT 'Both',
          status TEXT DEFAULT 'Registered', last_seen TEXT,
          created_at TEXT NOT NULL,
          FOREIGN KEY(astronaut_id) REFERENCES astronauts(id)
        );
        CREATE TABLE IF NOT EXISTS records(
          id INTEGER PRIMARY KEY AUTOINCREMENT, astronaut_id INTEGER, device_code TEXT,
          timestamp TEXT NOT NULL, heart_rate REAL, spo2 REAL, skin_temp REAL,
          respiration REAL, movement REAL, sleep_hours REAL, stress TEXT,
          source TEXT DEFAULT 'Manual', raw_json TEXT,
          FOREIGN KEY(astronaut_id) REFERENCES astronauts(id)
        );
        CREATE TABLE IF NOT EXISTS alerts(
          id INTEGER PRIMARY KEY AUTOINCREMENT, astronaut_id INTEGER NOT NULL, metric TEXT NOT NULL,
          severity TEXT NOT NULL, message TEXT NOT NULL, value TEXT, record_id INTEGER,
          status TEXT DEFAULT 'OPEN', created_at TEXT NOT NULL, updated_at TEXT,
          acknowledged_at TEXT, resolved_at TEXT
        );
        CREATE TABLE IF NOT EXISTS psych_checkins(
          id INTEGER PRIMARY KEY AUTOINCREMENT, astronaut_id INTEGER NOT NULL, timestamp TEXT NOT NULL,
          gad1 INTEGER, gad2 INTEGER, ucla1 INTEGER, ucla2 INTEGER, ucla3 INTEGER,
          stress_self REAL, note TEXT DEFAULT ''
        );
        CREATE TABLE IF NOT EXISTS external_assessments(
          id INTEGER PRIMARY KEY AUTOINCREMENT, astronaut_id INTEGER NOT NULL,
          assessment_type TEXT NOT NULL, result TEXT NOT NULL, performed_at TEXT NOT NULL,
          notes TEXT DEFAULT '', source TEXT DEFAULT 'External clinical assessment'
        );
        """)
        def add_column(table, column, definition):
            existing = {row[1] for row in c.execute(f"PRAGMA table_info({table})").fetchall()}
            if column not in existing:
                c.execute(f"ALTER TABLE {table} ADD COLUMN {column} {definition}")
        for col, definition in [("nationality", "TEXT DEFAULT ''"), ("height_cm", "REAL"), ("weight_kg", "REAL")]:
            add_column("astronauts", col, definition)
        for col, definition in [
            ("bp_systolic", "REAL"), ("bp_diastolic", "REAL"), ("stress_level", "REAL"),
            ("suit_phase", "TEXT DEFAULT 'IVA'"), ("co2_environment_ppm", "REAL"),
            ("etco2_mmhg", "REAL"), ("activity_level", "REAL"),
            ("radiation_rate_usvh", "REAL"), ("radiation_dose_msv", "REAL"),
            ("pma_score", "REAL"), ("pma_source", "TEXT"), ("blood_glucose_mgdl", "REAL")
        ]:
            add_column("records", col, definition)
        add_column("devices", "suit_phase", "TEXT DEFAULT 'IVA'")
init_db()

def query(sql, params=()):
    with db() as c:
        return c.execute(sql, params).fetchall()

def execute(sql, params=()):
    with db() as c:
        cur = c.execute(sql, params)
        return cur.lastrowid

def calculate_pma(activity_level, movement):
    """Telemetry-derived activity indicator (0-100); not a medical diagnosis."""
    values = [float(v) for v in (activity_level, movement) if v is not None]
    if not values:
        return None
    # Prefer the dedicated activity sensor; fall back to the existing movement channel.
    return round(max(0.0, min(100.0, values[0])), 1)

def nasa_reference_note():
    return ("NASA standards are the authority for spaceflight medical/operational requirements, "
            "but they are not a public live database of disease-specific personal readings. "
            "This demo combines NASA spaceflight context with ADA/AHA clinical reference material; "
            "synthetic scenarios are clearly labeled and are not NASA-approved medical limits.")

