# =====================================================================
# NASA-Style Authentication Gate
# =====================================================================
if "authenticated" not in st.session_state:
    st.session_state["authenticated"] = False

if not st.session_state["authenticated"]:
    _, center_col, _ = st.columns([1.05, 1, 1.05])
    with center_col:
        now_utc = datetime.now().astimezone().strftime("%Y-%j // %H:%M:%S UTC%z")
        st.markdown(f"""
        <style>div[data-testid="stForm"]{{border-top:none !important;border-radius:0 0 14px 14px !important;padding:14px 18px 8px !important;}}</style>
        <div class="nasa-login-box">
            <img class="nv-login-logo" src="{logo_data_uri()}" alt="AESS NOVA logo">
            <div class="nasa-badge">AESS NOVA // FLIGHT OPERATIONS</div>
            <h1 class="nasa-title">NOVACARE MISSION CONTROL</h1>
            <div class="nasa-sub">Biomedical Telemetry & Crew Health Surveillance System</div>
        </div>
        """, unsafe_allow_html=True)

        with st.form("nasa_auth_form"):
            st.markdown('<span class="mono" style="font-size:12px;color:#9fb8cc;">CREW SURGEON / OPERATOR CREDENTIALS</span>', unsafe_allow_html=True)
            u_in = st.text_input("OPERATOR ID (USERNAME)", placeholder="Enter flight surgeon ID")
            p_in = st.text_input("SECURITY PASSCODE", type="password", placeholder="••••••••")
            login_btn = st.form_submit_button("INITIALIZE TELEMETRY LINK ➔", use_container_width=True)

        if login_btn:
            entered_hash = hashlib.sha256(p_in.encode()).hexdigest()
            if u_in.strip() == ADMIN_USER and entered_hash == ADMIN_PASS_HASH:
                st.session_state["authenticated"] = True
                st.session_state["operator"] = u_in.strip()
                st.rerun()
            else:
                st.error("⛔ ACCESS DENIED: Invalid Operator ID or Security Passcode.")

        st.markdown(f"""
            <div class="nasa-telemetry-bar">
                <span>SYS: SECURE-TLS</span>
                <span>MET: {now_utc}</span>
                <span>NODE: HOUSTON-JORDAN-01</span>
            </div>
        """, unsafe_allow_html=True)
    st.stop()

# =====================================================================
# General health reference ranges & Logic
# =====================================================================
RANGES = {
    "heart_rate": dict(label="Heart rate", unit="BPM", normal=(60, 100), watch=(50, 120), scale=(30, 160),
        normal_text="60–100", watch_text="50–59 · 101–120", crit_text="below 50 · above 120",
        about="Resting heart rate of a healthy adult. Exercise, caffeine and stress raise it temporarily."),
    "spo2": dict(label="Blood oxygen", unit="%", normal=(95, 100), watch=(91, 100), scale=(85, 100),
        normal_text="95–100", watch_text="91–94", crit_text="below 91",
        about="Oxygen saturation of the blood (SpO₂). Wearable sensors can read a little low with cold hands or movement."),
    "bp_systolic": dict(label="Blood pressure · systolic", unit="mmHg", normal=(90, 119), watch=(85, 159), scale=(70, 190),
        normal_text="90–119", watch_text="85–89 · 120–159", crit_text="below 85 · 160 or higher",
        about="The top number: pressure while the heart beats."),
    "bp_diastolic": dict(label="Blood pressure · diastolic", unit="mmHg", normal=(60, 79), watch=(50, 99), scale=(40, 120),
        normal_text="60–79", watch_text="50–59 · 80–99", crit_text="below 50 · 100 or higher",
        about="The bottom number: pressure between heartbeats."),
    "skin_temp": dict(label="Skin temperature", unit="°C", normal=(32.0, 35.5), watch=(30.0, 37.5), scale=(28, 40),
        normal_text="32.0–35.5", watch_text="30.0–31.9 · 35.6–37.5", crit_text="below 30.0 · above 37.5",
        about="Skin reads cooler than the body core (about 36.1–37.2 °C) and changes with the room and clothing."),
    "respiration": dict(label="Respiration", unit="breaths/min", normal=(12, 20), watch=(10, 24), scale=(4, 32),
        normal_text="12–20", watch_text="10–11 · 21–24", crit_text="below 10 · above 24",
        about="Breaths per minute at rest."),
    "stress_level": dict(label="Stress level", unit="/10", normal=(0, 3.9), watch=(0, 6.9), scale=(0, 10),
        normal_text="0–3", watch_text="4–6", crit_text="7–10",
        about="Self-reported or estimated score. 0 means no stress, 10 means the highest stress. There is no clinical standard."),
    "blood_glucose_mgdl": dict(label="Blood glucose", unit="mg/dL", normal=(70, 180), watch=(54, 250), scale=(40, 300),
        normal_text="70–180 (illustrative CGM band)", watch_text="54–69 · 181–250", crit_text="below 54 · above 250",
        about="Optional glucose-sensor channel. Individual targets and meal timing matter; not inferred from heart rate or SpO₂."),
    "sleep_hours": dict(label="Sleep", unit="h", normal=(7, 9), watch=(5, 10), scale=(0, 12),
        normal_text="7–9", watch_text="5–6.9 · 9.1–10", crit_text="below 5 · above 10",
        about="Hours of sleep in the last night. Most adults need 7 to 9."),
    "bmi": dict(label="Body mass index", unit="kg/m²", normal=(18.5, 24.9), watch=(16, 34.9), scale=(12, 40),
        normal_text="18.5–24.9", watch_text="16–18.4 · 25–34.9", crit_text="below 16 · 35 or higher",
        about="Weight divided by height squared. It does not separate muscle from fat, so athletes can read high."),
    # --- Spacecraft interior sensors (bands derived from published NASA figures; not official NASA alarm limits) ---
    "co2_environment_ppm": dict(label="Cabin CO₂", unit="ppm", normal=(0, 3950), watch=(0, 6975), scale=(0, 10000),
        normal_text="0–3,950", watch_text="3,951–6,975", crit_text="above 6,975",
        about="Spacecraft interior CO₂ sensor. ISS flight rules keep CO₂ near 3 mmHg (about 3,950 ppm); the NASA 7–180 day limit (SMAC) is 5.3 mmHg (about 6,975 ppm). Crews have reported headaches below that limit."),
    "radiation_rate_usvh": dict(label="Space radiation dose rate", unit="µSv/h", normal=(0, 30), watch=(0, 54), scale=(0, 80),
        normal_text="0–30", watch_text="31–54", crit_text="above 54",
        about="Interior radiation sensor. ISS crews typically receive about 0.2–0.65 mSv/day (8–27 µSv/h). NASA's free-space cosmic-ray design bound is 1.3 mSv/day (about 54 µSv/h). A sudden jump can point to a solar particle event."),
    "radiation_dose_msv": dict(label="Cumulative radiation dose", unit="mSv", normal=(0, 300), watch=(0, 480), scale=(0, 600),
        normal_text="0–300", watch_text="301–480", crit_text="above 480",
        about="Mission dose against the NASA career limit of 600 mSv (NASA-STD-3001 Vol. 1). Warnings start at 50% and 80% of that limit; earlier career dose is not included."),
}
ALERT_KEYS = ["heart_rate", "spo2", "bp_systolic", "bp_diastolic", "skin_temp", "respiration", "stress_level", "sleep_hours", "blood_glucose_mgdl",
              "co2_environment_ppm", "radiation_rate_usvh", "radiation_dose_msv"]
BASELINES = [("Heart rate", "heart_rate", "baseline_hr", "BPM"),
             ("Blood oxygen", "spo2", "baseline_spo2", "%"),
             ("Skin temperature", "skin_temp", "baseline_temp", "°C")]

SEV_COLORS = {"NORMAL": "#2aa879", "WATCH": "#d99b35", "CRITICAL": "#d94f65", "UNKNOWN": "#7890a8"}
SEV_RANK = {"UNKNOWN": 0, "NORMAL": 1, "WATCH": 2, "CRITICAL": 3}
STATE_LABEL = {"NORMAL": "Nominal", "WATCH": "Monitor", "CRITICAL": "Critical", "UNKNOWN": "No data"}
STATE_MEANING = {"NORMAL": "Within the expected range. Routine monitoring only.",
                 "WATCH": "Outside the expected range. Needs closer observation and a repeat measurement.",
                 "CRITICAL": "Far outside the expected range. Needs immediate review by the flight surgeon."}
STALE_AFTER = timedelta(hours=24)
OFFLINE_WATCH_MIN, OFFLINE_CRIT_MIN = 10, 60

def classify(key, value):
    if value is None:
        return "UNKNOWN", None
    r, v = RANGES[key], float(value)
    nlo, nhi = r["normal"]
    wlo, whi = r["watch"]
    if nlo <= v <= nhi:
        return "NORMAL", None
    direction = "low" if v < nlo else "high"
    if wlo <= v <= whi:
        return "WATCH", direction
    return "CRITICAL", direction

def worst_state(states):
    states = list(states)
    return max(states, key=lambda s: SEV_RANK[s]) if states else "UNKNOWN"

def fmt_val(v):
    return f"{round(float(v), 1):g}"

def sp(unit):
    return unit if unit in ("%", "/10") else " " + unit

def calc_bmi(height_cm, weight_kg):
    if height_cm and weight_kg and float(height_cm) > 0:
        return float(weight_kg) / ((float(height_cm) / 100) ** 2)
    return None

def parse_ts(s):
    try:
        d = datetime.fromisoformat(s)
    except Exception:
        return None
    return d.astimezone() if d.tzinfo is None else d

def ago(s):
    t = parse_ts(s) if s else None
    if t is None:
        return "never"
    sec = max(0, int((datetime.now().astimezone() - t).total_seconds()))
    if sec < 90: return f"{sec} s ago"
    if sec < 5400: return f"{sec // 60} min ago"
    if sec < 172800: return f"{sec // 3600} h ago"
    return t.strftime("%d %b %Y")

def metric_label(metric):
    if metric.startswith("baseline:"):
        return RANGES[metric.split(":", 1)[1]]["label"] + " vs personal baseline"
    if metric.startswith("device:"):
        return "Wearable connection · " + metric.split(":", 1)[1]
    if metric.startswith("psych:"):
        return {"psych:stress": "Psychological stress", "psych:anxiety": "Anxiety screen (GAD-2)",
                "psych:loneliness": "Loneliness screen (UCLA-3)", "psych:checkin": "Psychological check-in overdue"}.get(metric, "Psychological wellbeing")
    extra_labels = {
        "pma:low": "PMA activity indicator",
        "activity_level": "Activity sensor",
        "radiation_rate_usvh": "Radiation dose rate",
        "radiation_dose_msv": "Cumulative radiation dose",
        "co2_environment_ppm": "Cabin environmental CO₂",
        "etco2_mmhg": "Physiological EtCO₂",
    }
    if metric in extra_labels:
        return extra_labels[metric]
    return RANGES.get(metric, {}).get("label", metric.replace("_", " ").title())

def astronaut_options():
    rows = query("SELECT id,name,age FROM astronauts ORDER BY name")
    return {f"{r['name']} · {r['age']} yrs · #{r['id']}": r['id'] for r in rows}

def get_latest(astronaut_id):
    rows = query("SELECT * FROM records WHERE astronaut_id=? ORDER BY timestamp DESC,id DESC LIMIT 1", (astronaut_id,))
    return rows[0] if rows else None

def current_cabin_co2(aid):
    """Latest cabin CO2 reading (ppm) that is not stale; None when there is no fresh sensor value."""
    rows = query("SELECT co2_environment_ppm AS v, timestamp FROM records WHERE astronaut_id=? "
                 "AND co2_environment_ppm IS NOT NULL ORDER BY timestamp DESC, id DESC LIMIT 1", (aid,))
    if not rows:
        return None
    t = parse_ts(rows[0]["timestamp"])
    if t and datetime.now().astimezone() - t > STALE_AFTER:
        return None
    return float(rows[0]["v"])

def latest_value(aid, col):
    if col not in ALERT_KEYS:
        return None
    rows = query(f"SELECT {col} AS v, timestamp, id FROM records WHERE astronaut_id=? AND {col} IS NOT NULL "
                 "ORDER BY timestamp DESC, id DESC LIMIT 1", (aid,))
    return (rows[0]["v"], rows[0]["timestamp"], rows[0]["id"]) if rows else None

def latest_metrics(aid):
    out = {}
    for key in ALERT_KEYS:
        row = latest_value(aid, key)
        if row:
            out[key] = (row[0], row[1])
    return out

def reference_status(metric, value, age, baseline):
    if value is None: return "UNKNOWN", "No measurement available."
    if baseline is None: return "UNKNOWN", "Set a personal baseline before trend comparison."
    delta = abs(float(value) - float(baseline))
    limits = {"heart_rate": (10, 20), "spo2": (2, 4), "skin_temp": (0.8, 1.5), "sleep_hours": (1.5, 3)}
    watch, critical = limits.get(metric, (10, 20))
    if delta >= critical: return "CRITICAL", "Large change from this astronaut's baseline; review promptly."
    if delta >= watch: return "WATCH", "Change from personal baseline; repeat and review."
    return "NORMAL", "Close to personal baseline."

