def country_select(label, current="", key=None):
    options = [""] + COUNTRY_NAMES
    if current and current not in COUNTRY_CODES:
        options.insert(1, current)
    index = options.index(current) if current in options else 0
    return st.selectbox(label, options, index=index, key=key,
                        format_func=lambda n: "Select a country" if not n else (f"{flag_emoji(n)}  {n}" if n in COUNTRY_CODES else n))

# =====================================================================
# Psychological wellbeing model
# =====================================================================
GAD_CHOICES = {"Not at all": 0, "Several days": 1, "More than half the days": 2, "Nearly every day": 3}
UCLA_CHOICES = {"Hardly ever": 1, "Some of the time": 2, "Often": 3}
CHECKIN_DUE_DAYS = 7
PSYCH_ACTION = {"CRITICAL": "Arrange a private conversation with a behavioral health specialist as soon as possible.",
                "WATCH": "Check in with the crew member and repeat the screening soon.",
                "NORMAL": "No action needed.", "UNKNOWN": ""}
PSYCH_DOMAINS = [("stress", "Stress"), ("anxiety", "Anxiety"), ("loneliness", "Loneliness")]

def clip01(x):
    return max(0.0, min(1.0, x))

def anxiety_state(score):
    return "NORMAL" if score <= 2 else ("WATCH" if score <= 4 else "CRITICAL")

def loneliness_state(score):
    return "NORMAL" if score <= 4 else ("WATCH" if score <= 6 else "CRITICAL")

def strain_state(index):
    return "NORMAL" if index < 35 else ("WATCH" if index < 60 else "CRITICAL")

def fresh_value(m, key):
    e = m.get(key)
    if not e:
        return None
    t = parse_ts(e[1])
    if t and datetime.now().astimezone() - t > STALE_AFTER:
        return None
    return float(e[0])

def strain_index(person, m):
    parts = []
    hr = fresh_value(m, "heart_rate")
    if hr is not None:
        base = person["baseline_hr"] or 70
        parts.append(("Heart rate", clip01((hr - base) / 30), 0.30,
                      f'{fmt_val(hr)} BPM vs {fmt_val(base)} {"baseline" if person["baseline_hr"] else "typical resting"}'))
    rr = fresh_value(m, "respiration")
    if rr is not None:
        parts.append(("Breathing", clip01((rr - 16) / 10), 0.20, f"{fmt_val(rr)} breaths/min vs 16 typical"))
    sl = fresh_value(m, "sleep_hours")
    if sl is not None:
        parts.append(("Sleep", clip01((7 - sl) / 3), 0.25, f"{fmt_val(sl)} h vs 7 h needed"))
    sv = fresh_value(m, "stress_level")
    if sv is not None:
        parts.append(("Stress score", clip01(sv / 10), 0.25, f"{fmt_val(sv)}/10"))
    if len(parts) < 2:
        return None, "UNKNOWN", parts
    idx = 100 * sum(p[1] * p[2] for p in parts) / sum(p[2] for p in parts)
    return idx, strain_state(idx), parts

def psych_assessment(aid, person):
    m = latest_metrics(aid)
    rows = query("SELECT * FROM psych_checkins WHERE astronaut_id=? ORDER BY timestamp DESC, id DESC LIMIT 1", (aid,))
    chk = rows[0] if rows else None
    age_days, due = None, False
    if chk:
        t = parse_ts(chk["timestamp"])
        age_days = (datetime.now().astimezone() - t).days if t else None
        due = age_days is not None and age_days >= CHECKIN_DUE_DAYS
    idx, sstate, parts = strain_index(person, m)

    states, notes = [], []
    sv = fresh_value(m, "stress_level")
    if sv is not None:
        states.append(classify("stress_level", sv)[0]); notes.append(f"stress score {fmt_val(sv)}/10")
    if chk and not due and chk["stress_self"] is not None:
        states.append(classify("stress_level", chk["stress_self"])[0]); notes.append(f'self-reported {fmt_val(chk["stress_self"])}/10')
    if idx is not None:
        states.append(sstate); notes.append(f"physiological strain index {idx:.0f}/100")
    stress = (worst_state(states) if states else "UNKNOWN", ", ".join(notes) if notes else "No stress readings yet")

    if chk and not due and chk["gad1"] is not None and chk["gad2"] is not None:
        gad = chk["gad1"] + chk["gad2"]
        st_ = anxiety_state(gad)
        detail = f"GAD-2 score {gad}/6 (screening cut-off is 3)"
        if st_ != "NORMAL" and sstate in ("WATCH", "CRITICAL"):
            detail += "; physiology also shows elevated strain"
        anxiety = (st_, detail, gad)
    elif chk and due:
        anxiety = ("UNKNOWN", f"Last check-in was {age_days} days ago; a new one is due", None)
    else:
        anxiety = ("UNKNOWN", "No check-in recorded yet", None)

    if chk and not due and chk["ucla1"] is not None:
        uc = chk["ucla1"] + chk["ucla2"] + chk["ucla3"]
        lonely = (loneliness_state(uc), f"UCLA-3 score {uc}/9 (risk cut-off is about 5)", uc)
    elif chk and due:
        lonely = ("UNKNOWN", f"Last check-in was {age_days} days ago; a new one is due", None)
    else:
        lonely = ("UNKNOWN", "No check-in recorded yet", None)

    result = {"stress": stress, "anxiety": anxiety[:2], "loneliness": lonely[:2], "scores": (anxiety[2], lonely[2]),
              "strain": (idx, sstate, parts), "checkin": chk, "age_days": age_days, "due": due}
    result["overall"] = worst_state([stress[0], anxiety[0], lonely[0]])
    return result

# =====================================================================
# Alert engine
# =====================================================================
def alert_message(key, v, direction, state):
    r = RANGES[key]
    word = "below" if direction == "low" else "above"
    tail = "Re-check the reading and review promptly." if state == "CRITICAL" else "Re-measure and keep monitoring."
    return f'{r["label"]} is {fmt_val(v)}{sp(r["unit"])}, {word} the general range of {r["normal_text"]}{sp(r["unit"])}. {tail}'

def build_desired_alerts():
    now = datetime.now().astimezone()
    desired = {}
    for p in query("SELECT * FROM astronauts"):
        aid = p["id"]
        for key in ALERT_KEYS:
            row = latest_value(aid, key)
            if not row: continue
            v, ts, rid = row
            t = parse_ts(ts)
            if t and now - t > STALE_AFTER: continue
            state, direction = classify(key, v)
            if state in ("WATCH", "CRITICAL"):
                desired[(aid, key)] = (state, alert_message(key, v, direction, state), fmt_val(v), rid)
        latest_record = get_latest(aid)
        phase = (latest_record["suit_phase"] if latest_record and latest_record["suit_phase"] else "IVA")
        effective_base = disease_phase_baseline(p, phase, current_cabin_co2(aid))
        baseline_items = [
            (label, key, effective_base[key], unit)
            for label, key, _basekey, unit in BASELINES
        ] + [
            ("Systolic blood pressure", "bp_systolic", effective_base["bp_systolic"], "mmHg"),
            ("Diastolic blood pressure", "bp_diastolic", effective_base["bp_diastolic"], "mmHg"),
        ]
        for label, key, baseline, unit in baseline_items:
            row = latest_value(aid, key)
            if not row or baseline is None: continue
            v, ts, rid = row
            t = parse_ts(ts)
            if t and now - t > STALE_AFTER: continue
            state, _ = reference_status(key, v, p["age"], baseline)
            if state in ("WATCH", "CRITICAL"):
                diff = abs(float(v) - float(baseline))
                msg = (f'{label} is {fmt_val(v)}{sp(unit)}, {fmt_val(diff)}{sp(unit)} away from the '
                       f'{phase} disease-aware scenario baseline of {fmt_val(baseline)}{sp(unit)}.')
                desired[(aid, "baseline:" + key)] = (state, msg, fmt_val(v), rid)
        ps = psych_assessment(aid, p)
        for dom, dom_label in PSYCH_DOMAINS:
            dom_state, dom_detail = ps[dom][0], ps[dom][1]
            if dom_state in ("WATCH", "CRITICAL"):
                desired[(aid, "psych:" + dom)] = (dom_state, f"{dom_label}: {dom_detail}. {PSYCH_ACTION[dom_state]}", None, None)
        if ps["due"]:
            desired[(aid, "psych:checkin")] = ("WATCH", f'Last psychological check-in was {ps["age_days"]} days ago. A new check-in is due.',
                                               f'{ps["age_days"]} d', None)
    for d in query("SELECT * FROM devices WHERE astronaut_id IS NOT NULL AND last_seen IS NOT NULL AND status!='SIMULATION'"):
        t = parse_ts(d["last_seen"])
        if not t: continue
        minutes = int((now - t).total_seconds() // 60)
        if minutes >= OFFLINE_WATCH_MIN:
            state = "CRITICAL" if minutes >= OFFLINE_CRIT_MIN else "WATCH"
            desired[(d["astronaut_id"], "device:" + d["device_code"])] = (
                state, f'No data received from {d["device_code"]} for {minutes} min.', f"{minutes} min", None)
    return desired

def sync_alerts():
    stamp = datetime.now().astimezone().isoformat(timespec="seconds")
    desired = build_desired_alerts()
    with db() as c:
        existing = {(r["astronaut_id"], r["metric"]): r for r in
                    c.execute("SELECT * FROM alerts WHERE status IN ('OPEN','ACKNOWLEDGED')").fetchall()}
        for (aid, metric), (sev, msg, val, rid) in desired.items():
            ex = existing.get((aid, metric))
            if ex is None:
                c.execute("""INSERT INTO alerts(astronaut_id,metric,severity,message,value,record_id,status,created_at,updated_at)
                             VALUES(?,?,?,?,?,?,'OPEN',?,?)""", (aid, metric, sev, msg, val, rid, stamp, stamp))
            elif ex["severity"] != sev:
                escalated = SEV_RANK[sev] > SEV_RANK[ex["severity"]]
                status = "OPEN" if escalated else ex["status"]
                ack_at = None if escalated else ex["acknowledged_at"]
                c.execute("""UPDATE alerts SET severity=?,message=?,value=?,record_id=?,status=?,acknowledged_at=?,updated_at=?
                             WHERE id=?""", (sev, msg, val, rid, status, ack_at, stamp, ex["id"]))
            elif ex["message"] != msg or ex["record_id"] != rid:
                c.execute("UPDATE alerts SET message=?,value=?,record_id=?,updated_at=? WHERE id=?",
                          (msg, val, rid, stamp, ex["id"]))
        for key, ex in existing.items():
            if key not in desired:
                c.execute("UPDATE alerts SET status='RESOLVED',resolved_at=?,updated_at=? WHERE id=?", (stamp, stamp, ex["id"]))

# (the first sync_alerts() call now runs further down, after disease_phase_baseline is defined)

