def page_header(crumb, title, subtitle=None):
    st.markdown(f'<div class="nv-crumb">{esc(crumb)}</div>', unsafe_allow_html=True)
    st.title(title)
    if subtitle:
        st.caption(subtitle)

def section(title):
    st.markdown(f'<div class="nv-section">{esc(title)}</div>', unsafe_allow_html=True)

def chip(state):
    return f'<span class="nv-chip chip-{state}">{STATE_LABEL.get(state, state)}</span>'

def tile_html(label, value, tone="UNKNOWN"):
    return f'<div class="nv-tile tone-{tone}"><div class="nv-tile-k">{esc(label)}</div><div class="nv-tile-v">{value}</div></div>'

def track_gradient(key):
    r = RANGES[key]
    lo, hi = r["scale"]
    nlo, nhi = r["normal"]
    wlo, whi = r["watch"]
    p = lambda x: max(0.0, min(100.0, (x - lo) / (hi - lo) * 100))
    red, amber, green = SEV_COLORS["CRITICAL"], SEV_COLORS["WATCH"], SEV_COLORS["NORMAL"]
    stops = [(0, red), (p(wlo), red), (p(wlo), amber), (p(nlo), amber), (p(nlo), green),
             (p(nhi), green), (p(nhi), amber), (p(whi), amber), (p(whi), red), (100, red)]
    return "linear-gradient(90deg," + ",".join(f"{c} {x:.1f}%" for x, c in stops) + ")"

def track_html(key, value):
    lo, hi = RANGES[key]["scale"]
    marker = ""
    if value is not None:
        pos = max(0.0, min(100.0, (float(value) - lo) / (hi - lo) * 100))
        marker = f'<i style="left:{pos:.1f}%"></i>'
    return f'<div class="nv-track" style="background:{track_gradient(key)}">{marker}</div>'

def vital_html(key, value, foot=None):
    r = RANGES[key]
    state, _ = classify(key, value)
    val = (f'<div class="nv-val">{fmt_val(value)}<small>{r["unit"]}</small></div>' if value is not None
           else '<div class="nv-val nv-na">—</div>')
    foot = foot or f'Nominal {r["normal_text"]} {r["unit"]}'
    return (f'<div class="nv-vital s-{state}"><div class="nv-vital-top"><span class="nv-vital-name">{r["label"]}</span>'
            f'{chip(state)}</div>{val}{track_html(key, value)}<div class="nv-vital-foot">{foot}</div></div>')

def bp_html(m):
    s, d = m.get("bp_systolic"), m.get("bp_diastolic")
    sv, dv = (s[0] if s else None), (d[0] if d else None)
    state = worst_state([classify("bp_systolic", sv)[0], classify("bp_diastolic", dv)[0]])
    if sv is None and dv is None:
        val = '<div class="nv-val nv-na">—</div>'
    else:
        a = fmt_val(sv) if sv is not None else "—"
        b = fmt_val(dv) if dv is not None else "—"
        val = f'<div class="nv-val">{a}/{b}<small>mmHg</small></div>'
    foot = f'Nominal {RANGES["bp_systolic"]["normal_text"]} / {RANGES["bp_diastolic"]["normal_text"]} mmHg'
    return (f'<div class="nv-vital s-{state}"><div class="nv-vital-top"><span class="nv-vital-name">Blood pressure</span>'
            f'{chip(state)}</div>{val}{track_html("bp_systolic", sv)}<div class="nv-vital-foot">{foot}</div></div>')

def photo_src(photo):
    if not photo:
        return None
    photo = bytes(photo)
    mime = "image/png" if photo[:8] == b"\x89PNG\r\n\x1a\n" else "image/jpeg"
    return f"data:{mime};base64,{base64.b64encode(photo).decode()}"

def crew_card_html(p):
    src = photo_src(p["photo"])
    portrait = (f'<img src="{src}" alt="Portrait of {esc(p["name"])}">' if src
                else '<div class="nv-portrait-empty"><span>👨‍🚀</span><small>No portrait</small></div>')
    bmi = calc_bmi(p["height_cm"], p["weight_kg"])
    facts = [("Age", str(p["age"])),
             ("Nationality", (flag_img(p["nationality"]) + esc(p["nationality"])) if p["nationality"] else "—"),
             ("Height", f'{p["height_cm"]:g} cm' if p["height_cm"] else "—"),
             ("Weight", f'{p["weight_kg"]:g} kg' if p["weight_kg"] else "—"),
             ("BMI", fmt_val(bmi) if bmi else "—")]
    facts_html = "".join(f"<div><span>{k}</span><b>{v}</b></div>" for k, v in facts)
    notes = "".join(f'<span class="nv-note"><b>{lab}</b>{esc(p[k])}</span>' for lab, k in
                    (("Allergies", "allergies"), ("Surgeries", "surgeries"), ("Chronic conditions", "chronic_diseases")) if p[k])
    notes_html = f'<div class="nv-notes">{notes}</div>' if notes else ""
    return (f'<div class="nv-crew"><div class="nv-portrait">{portrait}</div><div>'
            f'<div class="nv-crew-name">{esc(p["name"])}</div>'
            f'<div class="nv-crew-mission">{esc(p["mission"] or "No mission assigned")}</div>'
            f'<div class="nv-facts">{facts_html}</div>{notes_html}</div></div>')

def alert_card_html(a, show_name=True):
    sev, status = a["severity"], a["status"]
    who = f'<span class="nv-alert-who">{esc(a["astronaut_name"])}</span>' if show_name else ""
    if status == "RESOLVED":
        meta = f'Resolved {ago(a["resolved_at"])}<br>Raised {ago(a["created_at"])}'
    elif status == "ACKNOWLEDGED":
        meta = f'Acknowledged {ago(a["acknowledged_at"])}<br>Raised {ago(a["created_at"])}'
    else:
        meta = f'Open<br>Raised {ago(a["created_at"])}<br>Updated {ago(a["updated_at"])}'
    dim = " dim" if status != "OPEN" else ""
    return (f'<div class="nv-alert sev-{sev}{dim}"><div><div class="nv-alert-top">{chip(sev)}'
            f'<b>{esc(metric_label(a["metric"]))}</b>{who}</div>'
            f'<div class="nv-alert-msg">{esc(a["message"])}</div></div><div class="nv-alert-meta">{meta}</div></div>')

def ref_card_html(key):
    r = RANGES[key]
