    alerts_rows = "".join(f"<tr><td>{a['severity']}</td><td>{esc(metric_label(a['metric']))}</td><td>{esc(a['message'])}</td><td>{a['status']}</td></tr>" for a in alerts[:20]) or "<tr><td colspan='4'>No alerts recorded.</td></tr>"
