def trend_fig(df, keys, title, height=280):
    fig = go.Figure()
    palette = ["#4cc9f0", "#8aa8ff"]
    shown = 0
    for i, k in enumerate(keys):
        if k in df.columns and df[k].notna().any():
            fig.add_trace(go.Scatter(x=df["timestamp"], y=df[k], mode="lines+markers", name=RANGES[k]["label"],
                                     connectgaps=True, line=dict(color=palette[i % 2], width=2), marker=dict(size=5)))
            nlo, nhi = RANGES[k]["normal"]
            fig.add_hrect(y0=nlo, y1=nhi, fillcolor="#2aa879", opacity=0.10, line_width=0)
            shown += 1
    if not shown:
        return None
    fig.update_layout(template="plotly_dark", paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(11,34,56,.55)",
                      height=height, margin=dict(l=10, r=10, t=48, b=10),
                      title=dict(text=title, font=dict(size=15)), font=dict(family="Manrope, sans-serif"),
                      legend=dict(orientation="h", y=1.14, x=0), xaxis=dict(showgrid=False), yaxis=dict(gridcolor="#1c3d58"))
    return fig

def render_charts(df, prefix):
    tabs = st.tabs(["Heart rate & oxygen", "Blood pressure", "Temperature & breathing", "Stress & sleep"])
    layout = [
        [[("heart_rate",), "Heart rate (BPM)"], [("spo2",), "Blood oxygen (%)"]],
        [[("bp_systolic", "bp_diastolic"), "Blood pressure (mmHg)"]],
        [[("skin_temp",), "Skin temperature (°C)"], [("respiration",), "Respiration (breaths/min)"]],
        [[("stress_level",), "Stress level (0–10)"], [("sleep_hours",), "Sleep (hours)"]],
    ]
    for ti, (tab, charts) in enumerate(zip(tabs, layout)):
        with tab:
            cols = st.columns(len(charts))
            for ci, (col, (keys, title)) in enumerate(zip(cols, charts)):
                with col:
                    fig = trend_fig(df, list(keys), title)
                    if fig is None:
                        st.caption(f"No {title.split(' (')[0].lower()} readings recorded yet.")
                    else:
                        st.plotly_chart(fig, use_container_width=True, key=f"{prefix}_{ti}_{ci}")

