def critical_alert_state():
    """Returns (all open critical alerts, those not yet announced in this session)."""
    rows = query("""SELECT al.id, al.metric, al.message, a.name FROM alerts al JOIN astronauts a ON a.id=al.astronaut_id
                    WHERE al.status='OPEN' AND al.severity='CRITICAL' ORDER BY al.updated_at DESC""")
    seen = st.session_state.setdefault("notified_alerts", set())
    return rows, [r for r in rows if r["id"] not in seen]

def notify_critical():
    """Called from the live dashboard fragment. A popup cannot open from inside a fragment,
    so when a new critical alert appears we re-run the whole app and the popup opens there."""
    rows, new = critical_alert_state()
    if new:
        st.rerun()
    return rows

