# Disease-aware educational simulation. These are scenario parameters, NOT NASA limits
# and NOT individualized clinical prescriptions. Phase offsets are illustrative workload
# assumptions only; real EVA/IVA responses vary by person, suit, workload and mission.
def detect_conditions(person):
    """Detect only explicitly recorded diabetes/hypertension terms in the crew profile."""
    text_conditions = str(person["chronic_diseases"] or "").lower()

    def mentioned(terms):
        for term in terms:
            for match in re.finditer(re.escape(term), text_conditions):
                prefix = text_conditions[max(0, match.start() - 65):match.start()]
                suffix = text_conditions[match.end():match.end() + 22]
                # Common English and Arabic negations; do not activate a disease profile
                # for entries such as "no diabetes", "لا يوجد سكري" or "ما عنده ضغط".
                negated_before = re.search(
                    r"(?:\bno\b|\bwithout\b|\bdenies\b|\bnegative for\b|"
                    r"\bnot diagnosed with\b|لا\s+يوجد|لا\s+يعاني\s+من|ليس\s+لديه|"
                    r"ما\s+عنده|ما\s+بعاني\s+من|ينفي|بدون)"
                    r"(?:\s+[\wء-ي]+){0,5}\s*$", prefix)
                negated_after = re.match(r"\s*(?:[:：-]?\s*)(?:no\b|لا\b|negative\b|منخفض|واطي|هابط)", suffix)
                if not negated_before and not negated_after:
                    return True
        return False

    diabetes = mentioned(("diabetes", "diabetic", "سكري", "داء السكري", "سكر", "type 1", "type 2", "t1d", "t2d"))
    hypertension = mentioned(("hypertension", "hypertensive", "high blood pressure", "ضغط", "ارتفاع ضغط"))
    return {"diabetes": diabetes, "hypertension": hypertension}


def disease_phase_baseline(person, phase="IVA", cabin_co2_ppm=None):
    """Profile-derived demo baselines; illustrative simulation values, not treatment targets."""
    conditions = detect_conditions(person)
    eva = str(phase).upper() == "EVA"
    # Start from the crew member's manually entered baseline where one exists.
    base = {
        "heart_rate": float(person["baseline_hr"] or 74),
        "spo2": float(person["baseline_spo2"] or 97.5),
        "skin_temp": float(person["baseline_temp"] or 33.4),
        "respiration": 16.0,
        "bp_systolic": 118.0,
        "bp_diastolic": 76.0,
        "stress_level": 3.0,
        "blood_glucose_mgdl": None,
    }
    # Disease selection automatically switches the relevant simulated channels
    # and their displayed baselines. These are fictional demo settings only.
    if conditions["hypertension"]:
        base["bp_systolic"] = 132.0
        base["bp_diastolic"] = 82.0
    if conditions["diabetes"]:
        base["blood_glucose_mgdl"] = 135.0
    # EVA uses a separate workload scenario. It is not a universal physiological rule.
    if eva:
        base["heart_rate"] += 6
        base["respiration"] += 1
        base["stress_level"] += 0.7
        if conditions["hypertension"]:
            base["bp_systolic"] += 4
            base["bp_diastolic"] += 2
        if conditions["diabetes"]:
            base["blood_glucose_mgdl"] = 145.0
    # Environment-aware baseline: higher cabin CO2 nudges the expected breathing, heart rate and BP.
    # The direction follows CO2 physiology; the size of each step is an illustrative demo value,
    # not a NASA limit. Cabin air around 1,000 ppm is treated as neutral. Radiation at ISS-level
    # doses does not change vital signs, so it is tracked as an exposure alert instead.
    if cabin_co2_ppm is not None:
        excess = max(0.0, min(float(cabin_co2_ppm), 8000.0) - 1000.0) / 1000.0
        base["respiration"] += 0.4 * excess
        base["heart_rate"] += 1.0 * excess
        base["bp_systolic"] += 1.0 * excess
        base["bp_diastolic"] += 0.5 * excess
    return base

# Alerts depend on detect_conditions / disease_phase_baseline above, so the first sync runs here.
sync_alerts()

def demo_live_values(person, phase="IVA", previous=None, cabin_co2_ppm=None):
    conditions = detect_conditions(person)
    base = disease_phase_baseline(person, phase, cabin_co2_ppm)
    eva = str(phase).upper() == "EVA"
    vals = {
        "heart_rate": round(max(48, min(145, random.gauss(base["heart_rate"], 3.2))), 1),
        "spo2": round(max(94, min(100, random.gauss(base["spo2"], 0.45))), 1),
        "skin_temp": round(max(30, min(36.5, random.gauss(base["skin_temp"] + (0.25 if eva else 0), 0.25))), 1),
        "respiration": round(max(10, min(25, random.gauss(base["respiration"], 0.8))), 1),
        "bp_systolic": round(max(95, min(178, random.gauss(base["bp_systolic"], 4.0))), 0),
        "bp_diastolic": round(max(55, min(112, random.gauss(base["bp_diastolic"], 3.0))), 0),
        "stress_level": round(max(0, min(10, random.gauss(base["stress_level"], 0.7))), 1),
        "blood_glucose_mgdl": None,
    }
    if conditions["diabetes"]:
        # Most samples remain near common ADA targets; occasional excursions show
        # plausible post-meal hyperglycemia or low-glucose events for alert demonstrations.
        phase_center = base["blood_glucose_mgdl"]
        previous_glucose = previous["blood_glucose_mgdl"] if previous and previous["blood_glucose_mgdl"] is not None else None
        if previous_glucose is None:
            scenario = random.random()
            if scenario < 0.08:
                glucose = random.gauss(68, 4)       # initial simulated low-glucose case
            elif scenario < 0.20:
                glucose = random.gauss(192 if not eva else 185, 8)  # initial post-meal case
            else:
                glucose = random.gauss(phase_center, 8)
        else:
            # 30-second readings evolve gradually; mean reversion avoids implausible jumps.
            glucose = float(previous_glucose) + (phase_center - float(previous_glucose)) * 0.08 + random.gauss(0, 2.2)
        vals["blood_glucose_mgdl"] = round(max(50, min(260, glucose)), 0)
    # Preserve the original alert-demo behavior while keeping the disease/phase baseline.
    if random.random() > 0.15:
        groups = list(DEMO_ABNORMAL)
        if conditions["diabetes"]:
            groups.append("glucose")
        for group in random.sample(groups, random.choice([1, 2])):
            severity = random.choice(["CRITICAL", "WATCH"])
            if group == "blood_pressure":
                vals["bp_systolic"], vals["bp_diastolic"] = random.choice(DEMO_ABNORMAL[group][severity])
            elif group == "glucose":
                vals["blood_glucose_mgdl"] = random.choice((48, 52, 62, 188, 205, 235)) if severity == "CRITICAL" else random.choice((66, 68, 185, 195))
            else:
                key = group
                vals[key] = random.choice(DEMO_ABNORMAL[group][severity])
    # Non-disease profile gets no invented glucose channel.
    return vals

def maybe_simulate(astronaut_id):
    devices = query("SELECT * FROM devices WHERE astronaut_id=? AND status='SIMULATION'", (astronaut_id,))
    now = datetime.now().astimezone()
    for device in devices:
        last = parse_ts(device["last_seen"]) if device["last_seen"] else None
        if last and (now - last).total_seconds() < 25:
            continue
        demo_live = st.session_state.get("demo_live", False)
        person = query("SELECT * FROM astronauts WHERE id=?", (astronaut_id,))[0]
        phase = (st.session_state.get("demo_phase") if demo_live else device["suit_phase"]) or "IVA"
        previous_record = get_latest(astronaut_id)
        # Interior CO2 is generated first so the environment-aware baseline can follow it.
        co2_value = round(max(1500, min(9000, random.gauss(2800, 350))), 0)
        if random.random() < 0.12:
            co2_value = float(random.choice((4300, 5200, 6100, 7400)))   # demo excursion
        demo_values = demo_live_values(person, phase, previous_record, cabin_co2_ppm=co2_value)
        values = (demo_values["heart_rate"], demo_values["spo2"], demo_values["skin_temp"],
                  demo_values["respiration"], demo_values["bp_systolic"], demo_values["bp_diastolic"],
                  demo_values["stress_level"])
        glucose_value = demo_values["blood_glucose_mgdl"]
        stamp = now.isoformat(timespec="seconds")
        activity_value = round(max(0, min(100, random.gauss(54 if phase == "EVA" else 68, 12))), 1)
        etco2_value = round(max(20, min(60, random.gauss(38, 3))), 1)
        # Radiation: ISS-like interior rates (about 0.2-0.65 mSv/day); EVA is less shielded.
        radiation_rate = round(max(1.0, random.gauss(22.0 if phase == "EVA" else 15.0, 4.0 if phase == "EVA" else 2.5)), 2)
        if random.random() < 0.08:
            radiation_rate = float(random.choice((34, 41, 58)))          # demo spike (belt pass / particle event)
        prev_dose = query("SELECT radiation_dose_msv AS v FROM records WHERE astronaut_id=? AND radiation_dose_msv IS NOT NULL "
                          "ORDER BY timestamp DESC, id DESC LIMIT 1", (astronaut_id,))
        elapsed_h = min(((now - last).total_seconds() / 3600.0) if last else (30 / 3600.0), 1.0)
        radiation_dose = round((float(prev_dose[0]["v"]) if prev_dose else 0.0) + radiation_rate * elapsed_h / 1000.0, 6)
        execute("""INSERT INTO records(astronaut_id,device_code,timestamp,heart_rate,spo2,skin_temp,respiration,
        bp_systolic,bp_diastolic,stress_level,source,suit_phase,co2_environment_ppm,etco2_mmhg,
        activity_level,radiation_rate_usvh,pma_score,pma_source,blood_glucose_mgdl,radiation_dose_msv)
        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (astronaut_id, device["device_code"], stamp, values[0], values[1], values[2], values[3],
                 values[4], values[5], values[6], DEMO_SOURCE if demo_live else SIM_SOURCE,
                 phase, co2_value, etco2_value, activity_value,
                 radiation_rate, calculate_pma(activity_value, None),
                 "SIMULATED activity sensor — NOT a medical diagnosis", glucose_value, radiation_dose))
        execute("UPDATE devices SET last_seen=? WHERE id=?", (stamp, device["id"]))
    return [d["device_code"] for d in devices]

@st.fragment(run_every="30s")
def live_panel(aid):
    sim_codes = maybe_simulate(aid)
    sync_alerts()
    notify_critical()
    person = query("SELECT * FROM astronauts WHERE id=?", (aid,))[0]
    m = latest_metrics(aid)

    states = [classify(k, m[k][0])[0] for k in ALERT_KEYS if k in m]
    overall = worst_state(states) if states else "UNKNOWN"
    open_alerts = query("""SELECT * FROM alerts WHERE astronaut_id=? AND status IN ('OPEN','ACKNOWLEDGED')
                           ORDER BY CASE severity WHEN 'CRITICAL' THEN 0 ELSE 1 END, updated_at DESC""", (aid,))
    newest = max((v[1] for v in m.values()), default=None)
    n_open = sum(1 for a in open_alerts if a["status"] == "OPEN")
    active_devs = query("SELECT device_code, status FROM devices WHERE astronaut_id=?", (aid,))
    if sim_codes:
        wearable = f'{esc(", ".join(sim_codes))} · demo simulation'
    elif active_devs:
        wearable = esc(", ".join(f"{d['device_code']} ({d['status']})" for d in active_devs))
    else:
        wearable = "No active wearable"

    st.markdown(
        f'<div class="nv-strip"><div><span class="k">Wearable</span><b>{wearable}</b></div>'
        f'<div><span class="k">Last reading</span><b>{ago(newest)}</b></div>'
        f'<div><span class="k">Overall status</span>{chip(overall)}</div>'
        f'<div><span class="k">Open alerts</span><b>{n_open}</b></div></div>', unsafe_allow_html=True)

    bmi = calc_bmi(person["height_cm"], person["weight_kg"])
    r1 = st.columns(4)
    r2 = st.columns(4)
    cards = [(r1[0], vital_html("heart_rate", m["heart_rate"][0] if "heart_rate" in m else None)),
             (r1[1], vital_html("spo2", m["spo2"][0] if "spo2" in m else None)),
             (r1[2], bp_html(m)),
             (r1[3], vital_html("stress_level", m["stress_level"][0] if "stress_level" in m else None)),
             (r2[0], vital_html("skin_temp", m["skin_temp"][0] if "skin_temp" in m else None)),
             (r2[1], vital_html("respiration", m["respiration"][0] if "respiration" in m else None)),
             (r2[2], vital_html("sleep_hours", m["sleep_hours"][0] if "sleep_hours" in m else None)),
             (r2[3], vital_html("bmi", bmi, foot="Calculated from height and weight"))]
    for col, markup in cards:
        with col:
            st.markdown(markup, unsafe_allow_html=True)
    latest_glucose = get_latest(aid)
    if detect_conditions(person)["diabetes"]:
        st.metric("Simulated blood glucose", 
                  f"{latest_glucose['blood_glucose_mgdl']:.0f} mg/dL" if latest_glucose and latest_glucose["blood_glucose_mgdl"] is not None else "—",
                  help="Demo-only glucose value. The wearable does not measure glucose unless a dedicated validated glucose sensor is connected.")
        st.caption("Diabetes scenario: glucose is simulated separately; the wearable does not measure glucose unless a dedicated validated glucose sensor is connected.")
    baseline_phase = st.session_state.get("demo_phase", "IVA") if st.session_state.get("demo_live") and st.session_state.get("demo_aid") == aid else (dict(get_latest(aid) or {}).get("suit_phase") or "IVA")
    env_co2 = current_cabin_co2(aid)
    effective = disease_phase_baseline(person, baseline_phase, env_co2)
    st.caption(
        f"Automatic profile baseline · {baseline_phase} · "
        f"HR {effective['heart_rate']:.0f} BPM · BP {effective['bp_systolic']:.0f}/{effective['bp_diastolic']:.0f} mmHg"
        + (f" · Glucose {effective['blood_glucose_mgdl']:.0f} mg/dL" if effective["blood_glucose_mgdl"] is not None else "")
        + " · Derived automatically from the chronic-disease field; demo values only."
    )
    st.caption(
        f"Environment-aware baseline · {'Outside the vehicle (EVA)' if baseline_phase == 'EVA' else 'Inside the vehicle (IVA)'}"
        + (f" · Cabin CO₂ {env_co2:,.0f} ppm" if env_co2 is not None else " · No cabin CO₂ reading yet")
        + f" · Respiration {effective['respiration']:.1f}/min · The baseline shifts with the suit phase, the cabin CO₂ and any diabetes/hypertension in the profile."
    )

    section("Psychological wellbeing")
    ps = psych_assessment(aid, person)
    for col, (dom, dom_label) in zip(st.columns(3), PSYCH_DOMAINS):
        dom_state, dom_detail = ps[dom][0], ps[dom][1]
        with col:
            st.markdown(f'<div class="nv-card"><div class="nv-vital-top"><span class="nv-vital-name">{dom_label}</span>{chip(dom_state)}</div>'
                        f'<div class="nv-vital-foot" style="margin-top:10px">{esc(dom_detail)}</div></div>', unsafe_allow_html=True)

    section("Active alerts")
    if open_alerts:
        st.markdown("".join(alert_card_html(dict(a), show_name=False) for a in open_alerts), unsafe_allow_html=True)
    else:
        st.markdown('<div class="nv-clear">✓ All recorded readings are inside the general ranges.</div>', unsafe_allow_html=True)

    section("Recorded telemetry")
    rows = query("""SELECT * FROM (SELECT * FROM records WHERE astronaut_id=? ORDER BY timestamp DESC, id DESC LIMIT 300)
                    ORDER BY timestamp""", (aid,))
    if rows:
        render_charts(pd.DataFrame([dict(r) for r in rows]), f"dash{aid}")
    else:
        st.info("No health readings recorded for this astronaut yet.")

# =====================================================================
# Spacecraft interior sensors (CO2 + space radiation)
# =====================================================================
def sensor_card_html(key, value, foot, decimals=1):
    r = RANGES[key]
    state, _ = classify(key, value)
    val = (f'<div class="nv-val">{float(value):,.{decimals}f}<small>{r["unit"]}</small></div>' if value is not None
           else '<div class="nv-val nv-na">—</div>')
    return (f'<div class="nv-vital s-{state}"><div class="nv-vital-top"><span class="nv-vital-name">{r["label"]}</span>'
            f'{chip(state)}</div>{val}{track_html(key, value)}<div class="nv-vital-foot">{foot}</div></div>')

def first_present(rows, col):
    for r in rows:
        if r[col] is not None:
            return float(r[col]), r["timestamp"]
    return None, None

@st.fragment(run_every="30s")
def sensor_panel(aid):
    section("Spacecraft interior sensors · CO₂ & space radiation")
    rows = query("""SELECT * FROM records WHERE astronaut_id=? AND (co2_environment_ppm IS NOT NULL
                    OR radiation_rate_usvh IS NOT NULL OR radiation_dose_msv IS NOT NULL)
                    ORDER BY timestamp DESC, id DESC LIMIT 300""", (aid,))
    if not rows:
        st.info("No interior sensor readings yet. They arrive from the vehicle sensors (or the live demo) together with each telemetry packet.")
        return
    co2, co2_ts = first_present(rows, "co2_environment_ppm")
    rate, rate_ts = first_present(rows, "radiation_rate_usvh")
    dose, dose_ts = first_present(rows, "radiation_dose_msv")
    newest = max([t for t in (co2_ts, rate_ts, dose_ts) if t], default=None)
    c1, c2, c3, c4 = st.columns(4)
    with c1:
        foot = (f"≈ {co2 / 1316:.1f} mmHg · ISS rule 3 mmHg · NASA 180-day limit 5.3 mmHg" if co2 is not None
                else "Nominal 0–3,950 ppm")
        st.markdown(sensor_card_html("co2_environment_ppm", co2, foot, 0), unsafe_allow_html=True)
    with c2:
        foot = (f"≈ {rate * 24 / 1000:.2f} mSv/day · ISS typical 0.2–0.65 mSv/day" if rate is not None
                else "Nominal 0–30 µSv/h")
        st.markdown(sensor_card_html("radiation_rate_usvh", rate, foot, 1), unsafe_allow_html=True)
    with c3:
        foot = (f"{dose / 600 * 100:.2f}% of the 600 mSv NASA career limit" if dose is not None
                else "Compared with the 600 mSv NASA career limit")
        st.markdown(sensor_card_html("radiation_dose_msv", dose, foot, 3), unsafe_allow_html=True)
    with c4:
        per_day = (rate * 24 / 1000) if rate else None
        days_left = ((600 - (dose or 0)) / per_day) if per_day else None
        rows_html = (f'<div class="nv-strain-row"><span>Last sensor reading</span><b>{ago(newest)}</b></div>'
                     f'<div class="nv-strain-row"><span>Radiation per day</span><b>{f"{per_day:.2f} mSv" if per_day else "—"}</b></div>'
                     f'<div class="nv-strain-row"><span>Days to career limit*</span><b>{f"{days_left:,.0f}" if days_left else "—"}</b></div>'
                     f'<div class="nv-strain-row"><span>Cabin CO₂ in mmHg</span><b>{f"{co2 / 1316:.2f}" if co2 is not None else "—"}</b></div>')
        st.markdown(f'<div class="nv-card" style="min-height:166px"><div class="nv-vital-name" style="margin-bottom:8px">Exposure outlook</div>{rows_html}</div>',
                    unsafe_allow_html=True)
    st.caption("*At the current dose rate, counting this mission only. Bands come from NASA JSC 20584 (CO₂ limits) and NASA-STD-3001 Vol. 1 (radiation); "
               "they are demo alert bands, not official NASA alarm thresholds. Radiation at these levels does not change vital signs, "
               "so it raises exposure alerts, while CO₂ also shifts the expected breathing, heart rate and blood pressure baseline.")
    if any("SIMULATION" in str(r["source"]).upper() or "DEMO" in str(r["source"]).upper() for r in rows[:1]):
        st.warning("These interior sensor values are simulated, not live hardware measurements.")
    df = pd.DataFrame([dict(r) for r in reversed(rows)])
    g1, g2 = st.columns(2)
    for i, (col, (k, title)) in enumerate(zip((g1, g2), (("co2_environment_ppm", "Cabin CO₂ (ppm)"),
                                                          ("radiation_rate_usvh", "Radiation dose rate (µSv/h)")))):
        with col:
            fig = trend_fig(df, [k], title)
            if fig is None:
                st.caption(f"No {title.split(' (')[0].lower()} readings recorded yet.")
            else:
                st.plotly_chart(fig, use_container_width=True, key=f"sens_{aid}_{i}")

