            with c3: temp = st.number_input("Skin temperature (°C)", min_value=0.0, max_value=45.0, value=0.0)
            c4, c5, c6 = st.columns(3)
            with c4: resp = st.number_input("Respiration (breaths/min)", min_value=0.0, max_value=100.0, value=0.0)
            with c5: movement = st.number_input("Movement score", min_value=0.0, max_value=1000.0, value=0.0)
            with c6: sleep = st.number_input("Sleep hours", min_value=0.0, max_value=24.0, value=0.0)
